import {icon} from './icons.mjs';
import {api as platformApi,send as platformSend} from './platform.mjs';
import {escapeHtml as esc,id,classifyCapture} from './core.mjs';
import {currentTimeZone,dateInZone,operationDate} from './time.mjs';
export function integrationsMarkup(){return '<section id="integrations-panel" class="card" data-integrations="true" aria-label="Conexões e lembretes"><h2>Conexões e lembretes</h2><p role="status">Carregando suas conexões…</p></section>';}
const field=(label,name,value,type='text',attrs='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`;
export function createIntegrationsUI(ctx){
 const api=ctx.api||platformApi,send=ctx.send||platformSend;
 let inbox=null,push=null,busy=false,loadedAt=0,message='',code=null,transcript=null,epoch=0,unlinkReview=false,view='whatsapp',selectedAudio=null,discardReview=null;const drafts=new Map();const root=()=>document.querySelector('#integrations-panel');
 const button=(text,action,extra='')=>`<button type="button" class="outline" data-action="integration-${action}" ${extra}>${text}</button>`;
 const check=(label,name,on)=>`<label class="integration-check"><input type="checkbox" name="${name}" ${on?'checked':''}> ${label}</label>`;
 function rememberDrafts(){for(const form of root()?.querySelectorAll?.('form')||[]){const values={};for(const el of form.elements||[]){if(!el.name||el.type==='submit')continue;if(el.type==='file'){if(el.files?.[0])selectedAudio=el.files[0];continue;}values[el.name]={value:el.value,checked:el.checked};}drafts.set(form.id+(form.dataset.id||''),values);}}
 function restoreDrafts(){for(const form of root()?.querySelectorAll?.('form')||[]){const values=drafts.get(form.id+(form.dataset.id||''));for(const el of form.elements||[]){if(!el.name||!values?.[el.name]||el.type==='file')continue;const stored=values[el.name];if(el.type==='checkbox'||el.type==='radio'){if(!el.disabled)el.checked=stored.checked;}else el.value=stored.value;}if(busy)for(const el of form.elements||[])el.disabled=true;}}
 function setView(next,focus=false){if(!['whatsapp','audio','push'].includes(next))return;view=next;for(const panel of root()?.querySelectorAll?.('[data-integration-view]')||[])panel.hidden=panel.dataset.integrationView!==view;for(const tab of root()?.querySelectorAll?.('[role="tab"]')||[]){const active=tab.dataset.view===view;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;if(active&&focus)tab.focus({preventScroll:true});}}
 const unavailable=(title,description)=>`<div class="integration-unavailable">${icon('clock')}<div><strong>${title}</strong><p>${description}</p></div></div>`;
 const statusPill=(text,active=false)=>`<span class="connection-status ${active?'is-ready':''}"><i aria-hidden="true"></i>${text}</span>`;
 function receivedMarkup(){const items=inbox?.items||[];return `<section class="integration-received"><div class="section-head"><div><h3>Recebido do WhatsApp</h3><p>Revise antes de trazer para sua organização.</p></div><span class="badge">${items.length}</span></div>${items.length?items.map(item=>`<article class="capture-item"><div class="section-head"><h4>${esc(({text:'Mensagem de texto',audio:'Transcrição de áudio',image:'Imagem',document:'Documento'})[item.kind]||'Mensagem')}</h4><time>${new Date(item.created_at).toLocaleString('pt-BR')}</time></div><p>${esc(({pending:'Aguardando processamento',processing:'Processando…',failed:'Não foi possível processar',ready:'Pronto para revisar'})[item.status]||item.status)}</p>${item.error?`<p class="form-error" role="status">${esc(item.error)}</p>`:''}${item.status==='ready'?(item.payload?.document?`<p>${esc(item.payload.document.originalName)}</p>${button('Guardar na biblioteca','import-document',`data-id="${esc(item.id)}"`)}`:`<form id="integration-import-form-${esc(item.id)}" data-id="${esc(item.id)}"><label>Texto para organizar<textarea name="text" rows="3" maxlength="600" required>${esc(item.payload?.text||'')}</textarea></label><p class="form-help">Até 600 caracteres por sugestão. A mensagem original será preservada.</p><button class="primary" type="submit">Trazer para revisão ${icon('arrow')}</button></form>`):''}<div class="integration-message-actions">${button('Descartar mensagem','discard-review',`data-id="${esc(item.id)}"`)}</div></article>`).join(''):`<div class="integration-empty">${icon('link')}<p>Nenhuma mensagem recebida por aqui.</p><small>Depois de conectar seu número, suas mensagens aparecerão neste espaço.</small></div>`}</section>`;}
 function whatsappMarkup(){return `<div class="integration-detail-grid"><section><div class="section-head"><h3>Seu WhatsApp, conectado</h3>${statusPill(inbox?.linked?'Conectado':inbox?.configured?'Disponível':'Em configuração',Boolean(inbox?.linked))}</div><p>Envie uma mensagem para a Mentra e encontre a sugestão aqui, pronta para revisar.</p>${!inbox?.configured?unavailable('Disponível após a ativação','A integração está sendo preparada. Você já pode organizar mensagens pelo campo acima.'):inbox?.linked?`<div class="integration-linked">${icon('check')}<span>Número conectado <strong>${esc(inbox.linked.phone)}</strong></span>${button('Desconectar','unlink-review')}</div>`:`<form id="integration-link-form">${check('Quero receber mensagens e mídias e transcrever meus áudios com a Cloudflare','consent',false)}<button class="primary" type="submit" ${busy?'disabled':''}>Conectar meu número ${icon('arrow')}</button></form>`}${code?`<div class="integration-code-box"><p>Envie este comando do seu número para o WhatsApp empresarial da Mentra:</p><code class="integration-code">${esc(code.command)}</code><small>Válido até ${new Date(code.expiresAt).toLocaleTimeString('pt-BR')}.</small></div>`:''}<details class="integration-note"><summary>Como funciona e como desconectar</summary><p>As mensagens geram sugestões. Nenhum compromisso ou lançamento é confirmado automaticamente. Para desconectar, envie PARAR ao mesmo número ou use o botão desta tela. Pendências não importadas serão removidas; seus registros guardados permanecem na conta.</p></details></section>${receivedMarkup()}</div>`;}
 function audioMarkup(){return `<div class="integration-detail-grid"><section><div class="section-head"><h3>Do áudio para o próximo passo</h3>${statusPill(inbox?.audioConfigured?'Disponível':'Em configuração',Boolean(inbox?.audioConfigured))}</div><p>Selecione um áudio, confira a transcrição e escolha o que quer organizar.</p>${!inbox?.audioConfigured?unavailable('Transcrição em preparação','Você poderá enviar seus áudios assim que este serviço for ativado.'):`<form id="integration-audio-form"><label class="integration-upload">${icon('up')}<span>Escolher arquivo de áudio</span><small>WAV, OGG, WebM, MP3, M4A ou AAC · até 2 MB</small><input name="audio" type="file" accept="audio/wav,audio/ogg,audio/webm,audio/mpeg,audio/mp4,audio/aac,.m4a" ${selectedAudio?'':'required'}></label>${selectedAudio?`<p class="integration-file-summary">Arquivo selecionado: <strong>${esc(selectedAudio.name)}</strong></p>`:''}${check('Autorizo enviar este áudio à Cloudflare para transcrever','consent',false)}<button class="primary" type="submit" ${busy?'disabled':''}>Transcrever áudio ${icon('arrow')}</button></form>`}<details class="integration-note"><summary>Privacidade e limites da transcrição</summary><p>Seu áudio é enviado à Cloudflare Workers AI. O original não é guardado no aplicativo; o texto do processamento fica disponível por até 30 dias. Limite de 20 áudios distintos por dia UTC. Revise a transcrição: ela pode conter erros.</p></details></section><section class="integration-transcript"><h3>Revise nas suas palavras</h3>${transcript?`<form id="integration-transcript-form"><label>O que você quer organizar?<textarea name="text" maxlength="600" rows="7" required>${esc(transcript.text)}</textarea></label><p class="form-help">Até 600 caracteres por sugestão. A transcrição original será preservada.</p><button class="primary" type="submit">Guardar sugestão para revisar ${icon('arrow')}</button></form>`:`<div class="integration-empty">${icon('spark')}<p>Sua transcrição aparecerá aqui.</p><small>Você confere o texto antes de criar qualquer registro.</small></div>`}</section></div>`;}
 function pushMarkup(s,supported){const configured=Boolean(push?.configured);return `<div class="integration-detail-grid"><section><div class="section-head"><h3>Um aviso, no seu ritmo</h3>${statusPill(!configured?'Em configuração':push?.enabled?'Ativados':'Desativados',Boolean(push?.enabled))}</div><p>Escolha o que merece um lembrete. Os avisos são discretos, sem dados pessoais no banner.</p>${!configured?unavailable('Avisos em preparação','Você pode deixar seus horários preferidos definidos enquanto o serviço é ativado.'):push?.eligible===false?unavailable('Assinatura inativa','Ative sua assinatura para vincular este aparelho. Você já pode preparar os horários preferidos.'):!supported?unavailable('Navegador sem suporte','Abra a Mentra em um navegador compatível para ativar os avisos neste dispositivo.'):`<div class="integration-device"><div><span class="small-label">SEUS DISPOSITIVOS</span><p><strong>${Number(push?.devices||0)}</strong> vinculados à conta</p></div><div class="button-row">${button('Ativar neste dispositivo','subscribe',busy?'disabled':'')}${button('Desativar neste dispositivo','unsubscribe',busy?'disabled':'')}</div></div>`}<details class="integration-note"><summary>Como ativar no celular</summary><p>No iPhone ou iPad, abra este endereço no Safari, toque em Compartilhar e em Adicionar à Tela de Início. Abra a Mentra pelo ícone criado e toque em Ativar neste dispositivo. No Android, use a opção Instalar aplicativo ou Adicionar à tela inicial do navegador compatível. Se você já negou notificações, libere-as nas configurações do site antes de tentar novamente.</p><p>Não é necessário manter a tela aberta depois da ativação. A entrega depende das condições do aparelho.</p></details><p class="form-help">A entrega depende da conexão e das configurações do aparelho. Não há garantia de horário exato.</p><details class="integration-note"><summary>Cancelamento e privacidade dos avisos</summary><p>Concluir uma tarefa, cancelar um compromisso ou desligar os avisos impede os envios ainda não iniciados. Não há lembretes automáticos de doses. Horários de silêncio suprimem os avisos nesse intervalo.</p></details></section><section><h3>Suas preferências</h3><form id="integration-push-form">${configured?check('Receber lembretes da minha conta','enabled',push?.enabled):'<p class="form-help">O envio continua desligado até a ativação do serviço e sua autorização.</p>'}<fieldset class="integration-group"><legend>O que deseja lembrar?</legend>${check('Tarefas com prazo','tasks',s.tasks!==false)}${check('Compromissos da agenda','events',s.events!==false)}${check('Momentos Mentra','moments',s.moments===true)}</fieldset><div class="form-grid integration-delivery-times">${field('Horário das tarefas','taskTime',s.taskTime||'09:00','time','required')}<label>Antes do compromisso<select name="eventMinutes">${[0,5,10,15,30,60].map(n=>`<option value="${n}" ${n===(s.eventMinutes??10)?'selected':''}>${n===0?'No horário':n+' minutos antes'}</option>`).join('')}</select></label></div>${field('Fuso dos lembretes','timeZone',s.timeZone||currentTimeZone(),'text','required')}<fieldset class="integration-group"><legend>Horário de silêncio</legend><div class="form-grid">${field('Das','quietStart',s.quietStart||'22:00','time','required')}${field('Até','quietEnd',s.quietEnd||'07:00','time','required')}</div><p class="form-help">Use horários iguais para desativar o silêncio.</p></fieldset><button class="primary" type="submit" ${busy?'disabled':''}>Salvar preferências</button></form></section></div>`;}
 function paint(){const target=root();if(!target?.getAttribute?.('data-integrations'))return;const settings=push?.settings||{},supported=Boolean(globalThis.isSecureContext&&'serviceWorker' in navigator&&'PushManager' in window&&'Notification' in window),tabs=[['whatsapp','link','WhatsApp',inbox?.linked?'Conectado':inbox?.configured?'Conectar número':'Em configuração'],['audio','spark','Áudio',inbox?.audioConfigured?'Transcrever arquivo':'Em configuração'],['push','bell','Lembretes',push?.configured?(push.enabled?'Ativados':'Personalizar'):'Em configuração']];
 target.innerHTML=`<header class="integration-header"><div><span class="eyebrow">SEU JEITO DE ORGANIZAR</span><h2>Conexões e lembretes</h2><p>Traga suas mensagens e escolha quando quer receber um aviso.</p></div>${button(icon('reset')+' Atualizar','refresh',busy?'disabled':'')}</header><p class="integration-status ${message?'has-message':''}" role="status" aria-live="polite">${esc(message||(busy?'Atualizando suas conexões…':''))}</p><div class="integration-tabs" role="tablist" aria-label="Conexões disponíveis">${tabs.map(([key,i,label,description])=>`<button type="button" id="connection-tab-${key}" role="tab" aria-selected="${key===view}" aria-controls="connection-panel-${key}" tabindex="${key===view?0:-1}" data-action="integration-view" data-view="${key}"><span class="integration-tab-icon">${icon(i)}</span><span><strong>${label}</strong><small>${description}</small></span>${icon('arrow','integration-tab-arrow')}</button>`).join('')}</div>${[['whatsapp',whatsappMarkup()],['audio',audioMarkup()],['push',pushMarkup(settings,supported)]].map(([key,markup])=>`<section id="connection-panel-${key}" class="integration-tabpanel" role="tabpanel" aria-labelledby="connection-tab-${key}" data-integration-view="${key}" ${key===view?'':'hidden'}>${markup}</section>`).join('')}`;restoreDrafts();
 }
 async function load(){if(busy)return;rememberDrafts();busy=true;message='';paint();const token=epoch;try{const results=await Promise.all([api('integrations/inbox'),api('push')]);if(token!==epoch)return;[inbox,push]=results;loadedAt=Date.now();}catch(error){message=error.message;}finally{busy=false;paint();}}
 async function guarded(work){if(busy)return;rememberDrafts();busy=true;message='';paint();try{await work();}catch(error){message=error.message;}finally{busy=false;paint();}}
 async function storeCapture(text,{sourceInboxId,originalText,source='audio',sentAt,audioHash}={}){const clean=String(text||'').trim();if(!clean||clean.length>600)throw Error('Revise uma descrição com até 600 caracteres.');const state=ctx.getState();if(sourceInboxId&&state.inbox.some(c=>c.sourceInboxId===sourceInboxId))return true;const today=sentAt&&Number.isFinite(sentAt)?dateInZone(new Date(sentAt),currentTimeZone()):operationDate(),capture=ctx.financialCapture(clean,source,today)||{id:id(),source,...classifyCapture(clean,'text',today),confirmed:false};capture.sourceInboxId=sourceInboxId;capture.originalText=originalText||clean;if(audioHash)capture.audioHash=audioHash;capture.createdAt=new Date().toISOString();state.inbox.push(capture);if(ctx.save()===false){state.inbox=state.inbox.filter(c=>c.id!==capture.id);throw Error('A captura não pôde ser gravada; o conteúdo recebido foi preservado.');}if(!await ctx.flush())throw Error('A sugestão ficou pendente de sincronização. Resolva antes de confirmar o recebimento.');return true;}
 async function importItem(item,text){if(!item||item.status!=='ready')throw Error('Atualize a caixa antes de importar.');const snapshotEpoch=window.mentraDataEpoch||0;
 if(item.payload?.document){const state=ctx.getState();if(!state.documents.some(d=>d.sourceInboxId===item.id)){const d=item.payload.document;state.documents.unshift({...d,id:item.id,title:d.title||d.originalName,sourceInboxId:item.id,date:operationDate(),createdAt:new Date().toISOString(),trashed:false});if(ctx.save()===false){state.documents=state.documents.filter(d=>d.sourceInboxId!==item.id);throw Error('O original recebido foi preservado; resolva a sincronização.');}if(!await ctx.flush())throw Error('O original está pendente de sincronização. Resolva antes de continuar.');}}
 else await storeCapture(text,{sourceInboxId:item.id,originalText:item.payload.text,source:item.kind==='audio'?'audio':'whatsapp',sentAt:item.payload.sentAt,audioHash:item.payload.audioHash});
 if(!await ctx.flush())throw Error('Aguarde a confirmação da sincronização antes de importar.');if(snapshotEpoch!==(window.mentraDataEpoch||0))return;await send('integrations/inbox/'+item.id+'/ack',{});inbox.items=inbox.items.filter(i=>i.id!==item.id);message='Recebimento confirmado. A sugestão ainda exige revisão antes de virar registro.';ctx.render();}
 async function subscribe(){if(push?.eligible===false)throw Error('Ative sua assinatura antes de autorizar os avisos neste aparelho.');if(!push?.configured||!globalThis.isSecureContext||!navigator.serviceWorker||!window.PushManager||!globalThis.Notification)throw Error('Push indisponível neste ambiente.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('A permissão de notificações não foi concedida. Os demais recursos continuam disponíveis.');const registration=await navigator.serviceWorker.register('/push-sw.js',{scope:'/'});await navigator.serviceWorker.ready;const raw=atob(push.publicKey.replace(/-/g,'+').replace(/_/g,'/')),key=Uint8Array.from(raw,c=>c.charCodeAt(0));let subscription=await registration.pushManager.getSubscription();if(subscription?.options?.applicationServerKey){const current=new Uint8Array(subscription.options.applicationServerKey);if(current.length!==key.length||current.some((value,index)=>value!==key[index])){await send('push/subscription',{endpoint:subscription.endpoint},'DELETE');await subscription.unsubscribe();subscription=null;}}if(!subscription){subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});}const saved=await send('push/subscription',subscription.toJSON());if(Number.isInteger(saved.devices))push.devices=saved.devices;message='Dispositivo vinculado. Confira e salve quais lembretes deseja receber.';}
 async function unsubscribe(){if(!navigator.serviceWorker)return;const registration=await navigator.serviceWorker.getRegistration('/'),subscription=await registration?.pushManager.getSubscription();if(subscription){const removed=await send('push/subscription',{endpoint:subscription.endpoint},'DELETE');if(push&&Number.isInteger(removed.devices))push.devices=removed.devices;await subscription.unsubscribe().catch(()=>{});}message='Avisos desativados neste dispositivo.';}
 function handleClick(action,data){if(!action.startsWith('integration-'))return false;
  if(action==='integration-view'){setView(data.view,true);return true;}
  if(action==='integration-refresh'){void load();return true;}
  if(action==='integration-discard-review'){const item=inbox?.items.find(i=>i.id===data.id);if(!item)return true;discardReview=item.id;ctx.modal('Descartar esta mensagem?',`<p>A mensagem e a mídia pendente serão removidas desta caixa. Registros que você já guardou na sua organização permanecem disponíveis.</p><div class="modal-actions">${button('Cancelar','discard-cancel')}${button('Descartar mensagem','discard-confirm')}</div>`);return true;}
  if(action==='integration-discard-cancel'){ctx.closeModal();return true;}
  if(action==='integration-discard-confirm'){const itemId=discardReview;if(!itemId)return true;discardReview=null;ctx.closeModal();void guarded(async()=>{await send('integrations/inbox/'+itemId,{confirmed:true},'DELETE');inbox.items=inbox.items.filter(i=>i.id!==itemId);message='Mensagem descartada. Os registros já guardados permanecem na sua conta.';});return true;}
  if(action==='integration-unlink-review'){unlinkReview=true;ctx.modal('Desvincular WhatsApp?',`<p>Novas mensagens deixam de entrar. Pendências ainda não importadas serão removidas; os registros já guardados ficam na sua conta.</p>${button('Confirmar desvinculação','unlink-confirm')}`);return true;}
  if(action==='integration-unlink-confirm'){if(!unlinkReview)return true;unlinkReview=false;ctx.closeModal();void guarded(async()=>{await send('whatsapp/link',{},'DELETE');inbox.linked=null;inbox.items=[];code=null;message='WhatsApp desvinculado.';});}
  if(action==='integration-subscribe')void guarded(subscribe);
  if(action==='integration-unsubscribe')void guarded(unsubscribe);
  if(action==='integration-import-document')void guarded(()=>importItem(inbox?.items.find(i=>i.id===data.id)));
  return true;
 }
 function handleSubmit(form){if(!form.id.startsWith('integration-'))return false;if(!form.checkValidity()){form.reportValidity();return true;}const values=Object.fromEntries(new FormData(form));
  if(form.id==='integration-link-form')void guarded(async()=>{if(values.consent!=='on')throw Error('Confirme o recebimento antes de vincular.');code=await send('whatsapp/link',{consent:true});message='Código gerado. Envie-o do seu número e atualize as conexões.';});
  if(form.id==='integration-audio-form')void guarded(async()=>{if(values.consent!=='on')throw Error('Confirme o envio deste áudio para transcrição.');const file=values.audio?.size?values.audio:selectedAudio;if(!file?.size||file.size>2*1024*1024)throw Error('Selecione áudio de até 2 MB.');transcript=await api('audio/transcribe',{method:'POST',headers:{'Content-Type':file.type||({wav:'audio/wav',mp3:'audio/mpeg',m4a:'audio/mp4',ogg:'audio/ogg',webm:'audio/webm',aac:'audio/aac'}[file.name.split('.').pop().toLowerCase()]||'application/octet-stream')},body:file,signal:AbortSignal.timeout(75000)});message='Transcrição pronta. Confira o texto antes de organizar.';});
  if(form.id==='integration-transcript-form')void guarded(async()=>{if(!transcript)throw Error('Transcrição não encontrada.');await storeCapture(values.text,{originalText:transcript.text,audioHash:transcript.audioHash});transcript=null;selectedAudio=null;drafts.delete('integration-audio-form');drafts.delete('integration-transcript-form');message='Sugestão guardada para revisar e confirmar na caixa de entrada.';ctx.render();});
  if(form.id.startsWith('integration-import-form'))void guarded(()=>importItem(inbox?.items.find(i=>i.id===form.dataset.id),values.text));
  if(form.id==='integration-push-form')void guarded(async()=>{if(!await ctx.flush())throw Error('Resolva a sincronização antes de alterar os avisos.');const settings={timeZone:values.timeZone,taskTime:values.taskTime,eventMinutes:Number(values.eventMinutes),quietStart:values.quietStart,quietEnd:values.quietEnd,tasks:values.tasks==='on',events:values.events==='on',moments:values.moments==='on'};await send('push/settings',{enabled:values.enabled==='on',settings},'PUT');push={...push,settings,enabled:values.enabled==='on'};drafts.delete('integration-push-form');message='Preferências dos avisos salvas. O navegador e o aparelho controlam a entrega.';});
  return true;
 }
 return {handleKey(event){const tab=event.target.closest?.('[role=tab][data-view]');if(!tab)return false;const keys=['whatsapp','audio','push'],index=keys.indexOf(tab.dataset.view);let next;if(event.key==='ArrowRight')next=keys[(index+1)%3];else if(event.key==='ArrowLeft')next=keys[(index+2)%3];else if(event.key==='Home')next=keys[0];else if(event.key==='End')next=keys[2];else return false;event.preventDefault();setView(next,true);return true;},mount(){if(root()?.getAttribute?.('data-integrations')){if(!inbox&&Date.now()-loadedAt>1000)void load();else paint();}},handleClick,handleSubmit,beforeLogout:unsubscribe,routeChanged(){epoch++;code=null;transcript=null;selectedAudio=null;drafts.clear();discardReview=null;},cancelPending(){unlinkReview=false;discardReview=null;},refresh:load};
}
